import { useEffect, useRef, useState } from 'react'
import { MermaidBlock } from '@/components/review/MermaidBlock'
import { Prose } from '@/components/prose/Prose'
import { useResolvedTheme } from '@/hooks/useTheme'
import { NoticeBanner } from '@/components/NoticeBanner'
import type { GraphViewData } from './graphDesignModel'

/** Render IDs are generated by the owner; the accessible list remains usable for every renderer. */
export function GraphModelView({
  rendering,
  selectedIds,
  onSelect,
  zh,
}: {
  rendering: GraphViewData['renderings'][number]
  selectedIds: string[]
  onSelect(id: string): void
  zh: boolean
}) {
  const mount = useRef<HTMLDivElement>(null)
  const theme = useResolvedTheme()
  const [rendered, setRendered] = useState(false)
  useEffect(() => {
    if (rendering.format !== 'mermaid' || !mount.current) return
    const container = mount.current,
      stage = document.createElement('div')
    let disposed = false
    setRendered(false)
    void MermaidBlock.render(stage, rendering.source, theme).then(() => {
      if (disposed) return
      container.replaceChildren(...Array.from(stage.childNodes))
      for (const item of rendering.elementIndex) {
        const target = Array.from(container.querySelectorAll<SVGElement>('[id], [data-id]')).find(
          (node) =>
            node.id.includes(item.renderId) || node.getAttribute('data-id') === item.renderId,
        )
        if (!target) continue
        target.setAttribute('role', 'button')
        target.setAttribute('tabindex', '0')
        target.setAttribute('aria-label', item.label)
        const toggle = () => onSelect(item.elementId)
        target.addEventListener('click', toggle)
        target.addEventListener('keydown', (event) => {
          if (event.key === 'Enter' || event.key === ' ') {
            event.preventDefault()
            toggle()
          }
        })
      }
      setRendered(true)
    })
    return () => {
      disposed = true
    }
  }, [rendering, theme, onSelect])
  useEffect(() => {
    for (const item of rendering.elementIndex) {
      const target = Array.from(
        mount.current?.querySelectorAll<SVGElement>('[role="button"]') ?? [],
      ).find(
        (node) => node.id.includes(item.renderId) || node.getAttribute('data-id') === item.renderId,
      )
      target?.setAttribute('aria-pressed', String(selectedIds.includes(item.elementId)))
    }
  }, [rendered, rendering, selectedIds])
  return (
    <section aria-label={rendering.modelId}>
      {rendering.format === 'markdown' ? (
        <Prose body={rendering.source} />
      ) : (
        <div className="graph-design__diagram" ref={mount} />
      )}
      {!rendering.elementIndex.length && (
        <NoticeBanner tone="info">
          {zh
            ? '此图没有可定位的元素，请使用语义列表。'
            : 'Use the semantic list to select elements.'}
        </NoticeBanner>
      )}
    </section>
  )
}
